import{_ as a,a as t,c as s,ac as o}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Grafana API 与 MySQL 监控面板 JSON","description":"Grafana API QPS 与 MySQL 统计面板 JSON 导出","frontmatter":{"title":"Grafana API 与 MySQL 监控面板 JSON","description":"Grafana API QPS 与 MySQL 统计面板 JSON 导出","sources":[{"repository":"jekyall_blog","file":"_posts/DevOps/云原生/服务监控/监控json.md"}],"showdocs":{"topics":[{"id":"metrics","title":"指标与可视化","link":"/topics/metrics/"},{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"命令与查询","scope":"historical","audience":"general","group":"容器与运维","summary":"Grafana API QPS 与 MySQL 统计面板 JSON 导出","status":"active","related":[{"title":"指标：序列、标签、Counter 与直方图","link":"/systems/logging-monitoring/metrics/metric-model","kind":"知识专题","scope":"general","audience":"general"},{"title":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"指标与可视化：容量、录制规则与面板发布","link":"/systems/logging-monitoring/metrics/plus/practice/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"指标与面板：空图、统计口径与故障复盘","link":"/systems/logging-monitoring/metrics/diagnosis","kind":"排错与诊断","scope":"general","audience":"general"},{"title":"Grafana 多数据源与面板配置","link":"/systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"systems/logging-monitoring/metrics/plus/ecosystem/监控json.md","filePath":"systems/logging-monitoring/metrics/plus/ecosystem/监控json.md"}'),i={name:"systems/logging-monitoring/metrics/plus/ecosystem/监控json.md"};function n(r,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<p><span id="监控json"></span></p><h1 id="grafana-api-与-mysql-监控面板-json" tabindex="-1">Grafana API 与 MySQL 监控面板 JSON <a class="header-anchor" href="#grafana-api-与-mysql-监控面板-json" aria-label="Permalink to &quot;Grafana API 与 MySQL 监控面板 JSON {#grafana-api-与-mysql-监控面板-json}&quot;">​</a></h1><p>本文保存两个独立的历史 Dashboard：API 的 schemaVersion 为 18，MySQL 为 16。先确认下面的依赖，再选择一份 JSON 导入；两段配置不能拼成一个 JSON 对象。</p><ul><li><a href="#准备-数据源与指标">准备：数据源与指标</a></li><li><a href="#应用-选择并导入面板">应用：选择并导入面板</a></li><li><a href="#验证-从原始指标到图表">验证：从原始指标到图表</a></li><li><a href="#常见问题-空图与统计口径">常见问题：空图与统计口径</a></li><li><a href="#api-qps">API 完整 JSON</a> · <a href="#mysql-qps">MySQL 完整 JSON</a></li></ul><h2 id="准备-数据源与指标" tabindex="-1">准备：数据源与指标 <a class="header-anchor" href="#准备-数据源与指标" aria-label="Permalink to &quot;准备：数据源与指标 {#准备-数据源与指标}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面板</th><th>数据源与变量</th><th>必须先核对的指标</th></tr></thead><tbody><tr><td>API / Prometheus Service</td><td>Prometheus 类型的数据源变量 <code>datasource</code>；按 <code>job</code>、<code>endpoint</code>、<code>method</code>、<code>status</code> 筛选；<code>interval</code> 控制速率窗口，<code>quantile</code> 控制分位点</td><td><code>service_uptime</code>、<code>service_http_request_count_total</code>，请求/响应大小及耗时的 <code>_sum</code>、<code>_count</code>、<code>_bucket</code></td></tr><tr><td>MySQL / MySQL 详细统计</td><td>多处写死历史数据源名称 <code>192.0.2.10:8836</code>；<code>host</code> 来自 <code>label_values(mysql_up, instance)</code>，另有 <code>interval</code></td><td><code>mysql_global_status_*</code>、<code>mysql_global_variables_*</code>；内存对比还依赖 <code>node_memory_MemTotal_bytes</code></td></tr></tbody></table><p>这里的 IP:端口是导出时的数据源名称，不能据此推断当前 Prometheus 的访问地址。API 与 MySQL 的应用/Exporter 如何部署不在原记录中，应先在目标 Prometheus 确认指标存在。</p><p>MySQL 内存查询按 <code>instance</code> 联接数据库和节点指标。两类采集目标的标签必须能对应同一实例，否则即使两侧各有数据，比值面板也可能为空。旧版 MySQL、存储引擎或 Exporter 专属指标需逐项确认，不能要求每个目标都提供全部历史指标。</p><h2 id="应用-选择并导入面板" tabindex="-1">应用：选择并导入面板 <a class="header-anchor" href="#应用-选择并导入面板" aria-label="Permalink to &quot;应用：选择并导入面板 {#应用-选择并导入面板}&quot;">​</a></h2><ol><li>按目标下载下方 API 或 MySQL 的<strong>完整 JSON 文件</strong>，先在本地检查 JSON 能否解析，再导入目标 Grafana。</li><li>在目标 Grafana 的 Dashboard 导入入口上传该文件或粘贴 JSON。已有同 UID 面板时先确认是否覆盖；需要保留旧面板时另存副本。</li><li>API 面板核对 <code>datasource</code> 变量；MySQL 面板逐项核对面板和变量中的历史数据源引用，再选择有效的 <code>host</code>。</li><li>先选一个有数据的 job/host 和明确时间范围，在副本验证后再保存用于日常观察。</li></ol><p>完整导出保留旧 <code>graph</code>、<code>singlestat</code> 类型及原 UID、查询、布局。目标 Grafana 的版本和插件能力需在实际导入时确认；本文没有修改 schemaVersion 来伪装兼容。</p><h2 id="验证-从原始指标到图表" tabindex="-1">验证：从原始指标到图表 <a class="header-anchor" href="#验证-从原始指标到图表" aria-label="Permalink to &quot;验证：从原始指标到图表 {#验证-从原始指标到图表}&quot;">​</a></h2><p>先在 Prometheus/Grafana 查询入口执行对应原始指标：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service_http_request_count_total</span></span>
<span class="line"><span>mysql_up</span></span>
<span class="line"><span>mysql_global_status_uptime</span></span>
<span class="line"><span>node_memory_MemTotal_bytes</span></span></code></pre></div><ol><li>API：检查 job 和 endpoint 等标签确实有候选值，再观察 Requests QPS；有请求但为空时检查速率窗口内是否有足够采样。</li><li>MySQL：先确认所选 host 的 <code>mysql_up</code> 与 uptime，再看查询速率、连接数和内存。单个面板为空时回到该面板的完整表达式核对指标和标签。</li><li>选择已知有请求/查询的时间窗口，对照应用或数据库侧的行为；“成功导入”只证明配置可读，不能证明采集链路和统计口径正确。</li></ol><h2 id="常见问题-空图与统计口径" tabindex="-1">常见问题：空图与统计口径 <a class="header-anchor" href="#常见问题-空图与统计口径" aria-label="Permalink to &quot;常见问题：空图与统计口径 {#常见问题-空图与统计口径}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>从配置能确定的排查点</th></tr></thead><tbody><tr><td>API 的 endpoint 下拉缺少路径</td><td>变量查询排除了 <code>/metrics</code> 和状态码 <code>404</code>；先检查查询过滤条件</td></tr><tr><td>API 请求/响应大小标题写 per second</td><td>表达式是 <code>rate(_sum) / rate(_count)</code>，应按平均每次请求/响应大小理解，不能把标题当吞吐率</td></tr><tr><td>MySQL 所有图为空</td><td>先检查历史数据源名称与 host 变量；再检查实际 Exporter 的指标名称</td></tr><tr><td>MySQL 仅内存比值为空</td><td>对照 <code>on(instance)</code> 两侧标签和 node 指标，不要直接补零</td></tr><tr><td>旧面板类型无法显示</td><td>在测试副本中检查目标 Grafana 的兼容/迁移提示，保留原导出用于对照</td></tr></tbody></table><h2 id="api-qps" tabindex="-1">API QPS <a class="header-anchor" href="#api-qps" aria-label="Permalink to &quot;API QPS {#api-qps}&quot;">​</a></h2><details><summary>展开 Prometheus Service 完整导出（schemaVersion 18）</summary><p>完整文件：<a href="/article-files/bb66a9f2f428a648.json" download="">API QPS（json）</a>。保留原始内容，使用前请核对本文的版本与环境说明。</p></details><h2 id="mysql-qps" tabindex="-1">Mysql QPS <a class="header-anchor" href="#mysql-qps" aria-label="Permalink to &quot;Mysql QPS {#mysql-qps}&quot;">​</a></h2><details><summary>展开 MySQL 详细统计完整导出（schemaVersion 16）</summary><p>完整文件：<a href="/article-files/0af25334cfd0b370.json" download="">Mysql QPS（json）</a>。保留原始内容，使用前请核对本文的版本与环境说明。</p></details>`,21)])])}const u=a(i,[["render",n]]);export{h as __pageData,u as default};
